-- ------------------------------------------------------------------------------
-- FILE: 007_security_and_correctness.sql
-- ------------------------------------------------------------------------------

-- ==============================================================================
-- 007_security_and_correctness.sql
-- Resolves Phase A security audit findings:
-- 1. Privilege escalation protection on public.profiles
-- 2. Auth sign-up trigger populating public.profiles from auth.users
-- 3. Database-level last-owner invariant protection on public.restaurant_members
-- 4. Atomic restaurant creation RPC with automatic owner assignment
-- 5. Atomic category & product reordering RPCs
-- 6. Storage path and anonymous access policies
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. FIX PRIVILEGE ESCALATION ON public.profiles
-- ------------------------------------------------------------------------------
-- Trigger preventing non-super-admins from modifying platform_role, id, or email.
create or replace function public.protect_profile_sensitive_columns()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- Prevent altering identity/email directly
  if (NEW.id <> OLD.id) then
    raise exception 'Changing profile ID is not permitted.';
  end if;

  if (NEW.email <> OLD.email) then
    raise exception 'Changing profile email directly is not permitted.';
  end if;

  -- Only super administrators can modify platform_role
  if (NEW.platform_role is distinct from OLD.platform_role) and not public.is_super_admin() then
    raise exception 'Only super administrators can alter platform_role.';
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

drop trigger if exists tr_protect_profile_columns on public.profiles;
create trigger tr_protect_profile_columns
  before update on public.profiles
  for each row execute procedure public.protect_profile_sensitive_columns();

-- Revoke direct update on sensitive column platform_role from regular roles
revoke update (platform_role, id, email) on public.profiles from anon, authenticated;
grant update (name) on public.profiles to authenticated;

-- ------------------------------------------------------------------------------
-- 2. SIGN-UP TRIGGER on auth.users -> public.profiles
-- ------------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_name text;
begin
  v_name := coalesce(
    new.raw_user_meta_data->>'name',
    split_part(new.email, '@', 1)
  );

  insert into public.profiles (id, email, name, platform_role, created_at, updated_at)
  values (new.id, lower(new.email), v_name, null, now(), now())
  on conflict (id) do update
  set email = excluded.email,
      name = coalesce(public.profiles.name, excluded.name),
      updated_at = now();

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- ------------------------------------------------------------------------------
-- 3. LAST OWNER INVARIANT ON public.restaurant_members
-- ------------------------------------------------------------------------------
-- Rejects deleting, deactivating, or demoting the last active RESTAURANT_OWNER.
create or replace function public.protect_last_active_owner()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_remaining_owners integer;
begin
  -- Only trigger if an active owner is being deleted, demoted, or deactivated
  if (OLD.role = 'RESTAURANT_OWNER' and OLD.status = 'ACTIVE') then
    if (TG_OP = 'DELETE' or NEW.role <> 'RESTAURANT_OWNER' or NEW.status <> 'ACTIVE') then
      select count(*)
      into v_remaining_owners
      from public.restaurant_members
      where restaurant_id = OLD.restaurant_id
        and role = 'RESTAURANT_OWNER'
        and status = 'ACTIVE'
        and id <> OLD.id;

      if v_remaining_owners = 0 then
        raise exception 'Cannot remove, deactivate, or demote the last active owner of this restaurant.';
      end if;
    end if;
  end if;

  if (TG_OP = 'DELETE') then
    return OLD;
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

drop trigger if exists tr_protect_last_owner on public.restaurant_members;
create trigger tr_protect_last_owner
  before update or delete on public.restaurant_members
  for each row execute procedure public.protect_last_active_owner();

-- ------------------------------------------------------------------------------
-- 4. ATOMIC RESTAURANT CREATION RPC
-- ------------------------------------------------------------------------------
create or replace function public.create_restaurant(
  name_en text,
  name_ar text,
  slug text,
  currency text default 'EGP',
  cuisine_type text default ''
)
returns public.restaurants
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_user_email text;
  v_restaurant public.restaurants;
  v_now timestamptz := now();
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Authentication required to create a restaurant.';
  end if;

  select email into v_user_email from public.profiles where id = v_user_id;
  if v_user_email is null then
    raise exception 'Profile not found for authenticated user.';
  end if;

  -- Validate slug format
  if not (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$') then
    raise exception 'Choose a lowercase URL-safe slug.';
  end if;

  -- Check slug uniqueness
  if exists (select 1 from public.restaurants r where r.slug = slug and r.deleted_at is null) then
    raise exception 'That menu address is already in use.';
  end if;

  -- Create restaurant
  insert into public.restaurants (
    name_en, name_ar, slug, currency, cuisine_type,
    timezone, menu_status, status, created_at, updated_at
  ) values (
    name_en, name_ar, slug, coalesce(currency, 'EGP'), coalesce(cuisine_type, ''),
    'Africa/Cairo', 'DRAFT', 'ACTIVE', v_now, v_now
  ) returning * into v_restaurant;

  -- Assign creator as RESTAURANT_OWNER
  insert into public.restaurant_members (
    restaurant_id, profile_id, email, role, status, created_at, updated_at
  ) values (
    v_restaurant.id, v_user_id, v_user_email, 'RESTAURANT_OWNER', 'ACTIVE', v_now, v_now
  );

  -- Create default settings
  insert into public.restaurant_settings (
    restaurant_id, default_locale, opening_hours, created_at, updated_at
  ) values (
    v_restaurant.id, 'en',
    jsonb_build_object(
      'monday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00'))),
      'tuesday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00'))),
      'wednesday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00'))),
      'thursday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00'))),
      'friday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00'))),
      'saturday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00'))),
      'sunday', jsonb_build_object('closed', false, 'shifts', jsonb_build_array(jsonb_build_object('open', '09:00', 'close', '22:00')))
    ),
    v_now, v_now
  );

  -- Create default branding
  insert into public.restaurant_branding (
    restaurant_id, primary_color, secondary_color, background_color, text_color,
    template, radius, theme, font, created_at, updated_at
  ) values (
    v_restaurant.id, '#176b4d', '#d7aa5c', '#f7f4ed', '#17221d',
    'Modern', 'rounded', 'light', 'Inter', v_now, v_now
  );

  -- Create initial FREE subscription
  insert into public.subscriptions (
    restaurant_id, plan, starts_at, expires_at, status, notes, created_at, updated_at
  ) values (
    v_restaurant.id, 'FREE', v_now, v_now + interval '365 days', 'ACTIVE', 'Initial Plan', v_now, v_now
  );

  return v_restaurant;
end;
$$;

grant execute on function public.create_restaurant(text, text, text, text, text) to authenticated;

-- ------------------------------------------------------------------------------
-- 5. ATOMIC REORDER RPCs
-- ------------------------------------------------------------------------------
create or replace function public.reorder_categories(
  p_restaurant_id uuid,
  p_category_ids uuid[]
)
returns setof public.categories
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_idx integer := 0;
begin
  if not public.is_restaurant_member(p_restaurant_id, array['RESTAURANT_OWNER', 'RESTAURANT_MANAGER']::public.app_role[]) then
    raise exception 'Permission denied to reorder categories.';
  end if;

  foreach v_id in array p_category_ids loop
    update public.categories
    set sort_order = v_idx,
        updated_at = now()
    where id = v_id
      and restaurant_id = p_restaurant_id;

    v_idx := v_idx + 1;
  end loop;

  return query
  select * from public.categories
  where restaurant_id = p_restaurant_id
    and deleted_at is null
  order by sort_order;
end;
$$;

grant execute on function public.reorder_categories(uuid, uuid[]) to authenticated;

create or replace function public.reorder_products(
  p_restaurant_id uuid,
  p_category_id uuid,
  p_product_ids uuid[]
)
returns setof public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_idx integer := 0;
begin
  if not public.is_restaurant_member(p_restaurant_id, array['RESTAURANT_OWNER', 'RESTAURANT_MANAGER']::public.app_role[]) then
    raise exception 'Permission denied to reorder products.';
  end if;

  foreach v_id in array p_product_ids loop
    update public.products
    set sort_order = v_idx,
        updated_at = now()
    where id = v_id
      and restaurant_id = p_restaurant_id
      and category_id = p_category_id;

    v_idx := v_idx + 1;
  end loop;

  return query
  select * from public.products
  where restaurant_id = p_restaurant_id
    and category_id = p_category_id
    and deleted_at is null
  order by sort_order;
end;
$$;

grant execute on function public.reorder_products(uuid, uuid, uuid[]) to authenticated;

-- ------------------------------------------------------------------------------
-- FILE: 008_super_admin_bootstrap_and_menu_fix.sql
-- ------------------------------------------------------------------------------

-- ==============================================================================
-- 008_super_admin_bootstrap_and_menu_fix.sql
-- Resolves:
-- 1. F1: Privilege escalation trigger bypass for privileged DB roles (SQL Editor / CLI)
--    so project owners can bootstrap the initial SUPER_ADMIN safely without disabling triggers.
-- 2. F2: Fixes public.get_public_menu UUID min(id) on existing databases by overriding
--    with deterministic (order by created_at asc, id asc limit 1).
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. PRIVILEGE ESCALATION TRIGGER UPDATE (Allow privileged DB role bootstrap)
-- WARNING: The protect_profile_sensitive_columns() implementation below in 008
-- is SUPERSEDED by 009_profile_protection_security_definer_fix.sql.
-- Do NOT rely on 008's current_user check (which incorrectly bypassed all callers
-- inside SECURITY DEFINER). 009 fixes this with session_user check.
-- ------------------------------------------------------------------------------
create or replace function public.protect_profile_sensitive_columns()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_is_privileged boolean;
begin
  -- Check if executing under a privileged database role (postgres, supabase_admin, service_role, dashboard_user)
  -- or running in SQL editor / CLI without an active authenticated client session.
  v_is_privileged := (
    current_user in ('postgres', 'supabase_admin', 'service_role', 'dashboard_user') or
    session_user in ('postgres', 'supabase_admin', 'service_role', 'dashboard_user') or
    (auth.uid() is null and current_user not in ('authenticated', 'anon'))
  );

  -- If privileged DB role, permit administrative bootstrap / updates
  if v_is_privileged then
    NEW.updated_at := now();
    return NEW;
  end if;

  -- Prevent regular client connections (authenticated/anon) from altering identity/email
  if (NEW.id <> OLD.id) then
    raise exception 'Changing profile ID is not permitted.';
  end if;

  if (NEW.email <> OLD.email) then
    raise exception 'Changing profile email directly is not permitted.';
  end if;

  -- Only super administrators can modify platform_role
  if (NEW.platform_role is distinct from OLD.platform_role) and not public.is_super_admin() then
    raise exception 'Only super administrators can alter platform_role.';
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

-- ------------------------------------------------------------------------------
-- 2. GET_PUBLIC_MENU POSTGRESQL UUID COMPATIBILITY
-- ------------------------------------------------------------------------------
create or replace function public.get_public_menu(menu_slug text, branch_slug text default null)
returns jsonb language sql stable security definer set search_path=public as $$
  select jsonb_build_object(
    'restaurant',to_jsonb(r)-'deleted_at',
    'settings',jsonb_build_object('opening_hours',coalesce(b.opening_hours,s.opening_hours),'default_locale',s.default_locale),
    'branding',to_jsonb(rb),
    'categories',coalesce((select jsonb_agg(c order by c.sort_order) from public.categories c where c.restaurant_id=r.id and c.is_visible and c.deleted_at is null),'[]'::jsonb),
    'products',coalesce((select jsonb_agg(p order by p.sort_order) from public.products p join public.categories c on c.id=p.category_id where p.restaurant_id=r.id and p.is_visible and p.deleted_at is null and c.is_visible and c.deleted_at is null),'[]'::jsonb),
    'offers',coalesce((select jsonb_agg(o) from public.offers o where o.restaurant_id=r.id and o.is_active and o.deleted_at is null and now() between o.starts_at and o.ends_at),'[]'::jsonb),
    'branch',to_jsonb(b)
  ) from public.restaurants r
  join public.restaurant_settings s on s.restaurant_id=r.id
  join public.restaurant_branding rb on rb.restaurant_id=r.id
  left join public.branches b on b.restaurant_id=r.id and (b.slug=branch_slug or (branch_slug is null and b.id=(select b2.id from public.branches b2 where b2.restaurant_id=r.id order by b2.created_at asc, b2.id asc limit 1)))
  where r.slug=menu_slug and r.status='ACTIVE' and r.menu_status='PUBLISHED' and r.deleted_at is null
$$;

grant execute on function public.get_public_menu(text,text) to anon,authenticated;

-- ------------------------------------------------------------------------------
-- FILE: 009_profile_protection_security_definer_fix.sql
-- ------------------------------------------------------------------------------

-- ==============================================================================
-- 009_profile_protection_security_definer_fix.sql
-- Resolves:
-- 1. Security regression in 008: protect_profile_sensitive_columns() evaluated
--    `current_user` inside a SECURITY DEFINER function. Because current_user
--    is the function owner (postgres), the privileged bypass evaluated to true
--    for all callers.
-- 2. Fixed check: Privileged bypass applies ONLY when:
--    `auth.uid() is null AND session_user not in ('authenticator','anon','authenticated')`.
--    Never relies on current_user inside SECURITY DEFINER.
-- 3. Retains all 007 security invariants:
--    - Changing profile id is blocked.
--    - Changing profile email is blocked.
--    - Changing platform_role requires public.is_super_admin().
-- 4. Defense-in-depth column privileges:
--    Revoke table-level UPDATE on profiles from anon and authenticated,
--    and grant UPDATE strictly on (name) to authenticated.
-- ==============================================================================

create or replace function public.protect_profile_sensitive_columns()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_is_privileged boolean;
begin
  -- Privileged bypass ONLY when running without a JWT (auth.uid() is null)
  -- AND session_user is a privileged DB role (NOT the connection pooler or client roles).
  -- IMPORTANT: Never check current_user inside a SECURITY DEFINER function,
  -- as current_user resolves to the function owner (postgres) for all callers.
  v_is_privileged := (
    auth.uid() is null and
    session_user not in ('authenticator', 'anon', 'authenticated')
  );

  -- If genuinely executing from a privileged DB session (SQL Editor / CLI operator), permit update
  if v_is_privileged then
    NEW.updated_at := now();
    return NEW;
  end if;

  -- Prevent client connections from altering identity/email
  if (NEW.id <> OLD.id) then
    raise exception 'Changing profile ID is not permitted.';
  end if;

  if (NEW.email <> OLD.email) then
    raise exception 'Changing profile email directly is not permitted.';
  end if;

  -- Only super administrators can modify platform_role
  if (NEW.platform_role is distinct from OLD.platform_role) and not public.is_super_admin() then
    raise exception 'Only super administrators can alter platform_role.';
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

-- Defense in depth: restrict column-level UPDATE permissions
revoke update on public.profiles from anon, authenticated;
grant update (name) on public.profiles to authenticated;

-- ------------------------------------------------------------------------------
-- FILE: 010_team_invitations.sql
-- ------------------------------------------------------------------------------

-- ==============================================================================
-- MIGRATION 010: Team Invitations, Membership Status Expansion & Safe Claims
-- ==============================================================================
-- 1. Expands restaurant_members.status CHECK constraint to include 'SUSPENDED',
--    matching the TypeScript domain type and UI states, while verifying that
--    protect_last_active_owner continues to block suspending the last active owner.
-- 2. Restricts direct client INSERT on public.restaurant_members through RLS audit.
--    Membership creation must route through atomic create_restaurant RPC or
--    the SECURITY DEFINER public.invite_member RPC.
-- 3. Adds public.invite_member(p_restaurant_id, p_email, p_role) RPC:
--    - Enforces caller is an active RESTAURANT_OWNER or SUPER_ADMIN (mirroring
--      the src/services/authorization.ts team:write permission matrix).
--    - Rejects SUPER_ADMIN role assignments.
--    - Normalizes email to lower-case and checks duplicate membership.
--    - Looks up auth.users server-side: if an account exists AND email is confirmed,
--      sets status='ACTIVE' with profile_id. Otherwise creates status='PENDING'
--      with profile_id=NULL.
--    - Returns uniform restaurant_members record shape, preventing email enumeration.
-- 4. Safe pending membership claiming:
--    - Triggers on auth.users for new confirmations (INSERT with email_confirmed_at
--      or UPDATE transitioning email_confirmed_at from NULL to NOT NULL).
--    - Claims pending rows by setting profile_id and status='ACTIVE'.
--    - Prevents account takeover by ensuring unconfirmed sign-ups NEVER claim memberships.
-- 5. Hardens UPDATE on restaurant_members with tr_protect_membership_columns,
--    preventing modification of id, restaurant_id, email, or reassigning profile_id.
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. EXPAND STATUS CHECK CONSTRAINT
-- ------------------------------------------------------------------------------
alter table public.restaurant_members
  drop constraint if exists restaurant_members_status_check;

alter table public.restaurant_members
  add constraint restaurant_members_status_check
  check (status in ('ACTIVE', 'PENDING', 'SUSPENDED'));

-- ------------------------------------------------------------------------------
-- 2. RLS AUDIT & POLICY HARDENING ON public.restaurant_members
-- ------------------------------------------------------------------------------
-- Drop the overly broad 'FOR ALL' policy from migration 002
drop policy if exists members_owner_write on public.restaurant_members;

-- Separate into explicit UPDATE and DELETE policies for active owners
create policy members_owner_update on public.restaurant_members
  for update
  using (public.is_restaurant_member(restaurant_id, array['RESTAURANT_OWNER']::public.app_role[]))
  with check (public.is_restaurant_member(restaurant_id, array['RESTAURANT_OWNER']::public.app_role[]));

create policy members_owner_delete on public.restaurant_members
  for delete
  using (public.is_restaurant_member(restaurant_id, array['RESTAURANT_OWNER']::public.app_role[]));

-- Note: No direct INSERT policy is granted to anon or authenticated.
-- Direct client INSERT is blocked; all inserts must occur via trusted SECURITY DEFINER
-- routines (create_restaurant or invite_member).
grant select, update, delete on public.restaurant_members to authenticated;
revoke insert on public.restaurant_members from anon, authenticated;

-- ------------------------------------------------------------------------------
-- 3. MEMBERSHIP COLUMN IMMUTABILITY GUARD
-- ------------------------------------------------------------------------------
create or replace function public.protect_membership_columns()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Prevent altering immutable identity columns
  if (NEW.id <> OLD.id or NEW.restaurant_id <> OLD.restaurant_id or lower(NEW.email) <> lower(OLD.email)) then
    raise exception 'Cannot alter immutable membership identity columns (id, restaurant_id, email).';
  end if;

  -- Prevent reassigning profile_id once assigned
  if (OLD.profile_id is not null and NEW.profile_id is distinct from OLD.profile_id) then
    raise exception 'Cannot reassign profile_id of an active membership.';
  end if;

  -- Prevent assigning SUPER_ADMIN role
  if (NEW.role = 'SUPER_ADMIN') then
    raise exception 'Cannot assign SUPER_ADMIN role to a restaurant member.';
  end if;

  return NEW;
end;
$$;

revoke execute on function public.protect_membership_columns() from public, anon;

drop trigger if exists tr_protect_membership_columns on public.restaurant_members;
create trigger tr_protect_membership_columns
  before update on public.restaurant_members
  for each row execute procedure public.protect_membership_columns();

-- ------------------------------------------------------------------------------
-- 4. SERVER-SIDE INVITATION RPC
-- ------------------------------------------------------------------------------
-- Ensure auth.users has email_confirmed_at in test / offline environments
do $$
begin
  if exists (select 1 from information_schema.tables where table_schema = 'auth' and table_name = 'users') then
    if not exists (select 1 from information_schema.columns where table_schema = 'auth' and table_name = 'users' and column_name = 'email_confirmed_at') then
      alter table auth.users add column email_confirmed_at timestamptz;
    end if;
  end if;
end $$;

create or replace function public.invite_member(
  p_restaurant_id uuid,
  p_email text,
  p_role public.app_role
)
returns public.restaurant_members
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller_id uuid;
  v_is_owner boolean;
  v_email text;
  v_user_id uuid;
  v_confirmed_at timestamptz;
  v_member public.restaurant_members;
  v_now timestamptz := now();
begin
  -- 1. Authentication check
  v_caller_id := auth.uid();
  if v_caller_id is null then
    raise exception 'Authentication required to invite members.';
  end if;

  -- 2. Authorization check (mirroring TS team:write permission: ACTIVE RESTAURANT_OWNER or SUPER_ADMIN)
  select (public.is_super_admin() or exists (
    select 1 from public.restaurant_members
    where restaurant_id = p_restaurant_id
      and profile_id = v_caller_id
      and role = 'RESTAURANT_OWNER'
      and status = 'ACTIVE'
  )) into v_is_owner;

  if not coalesce(v_is_owner, false) then
    raise exception 'Unauthorized: only active restaurant owners can invite team members.';
  end if;

  -- 3. Reject SUPER_ADMIN role assignment
  if p_role = 'SUPER_ADMIN' or p_role not in ('RESTAURANT_OWNER', 'RESTAURANT_MANAGER', 'STAFF') then
    raise exception 'Invalid role for restaurant member.';
  end if;

  -- 4. Normalize and validate email
  v_email := lower(trim(p_email));
  if v_email is null or v_email = '' or position('@' in v_email) = 0 then
    raise exception 'Invalid email address.';
  end if;

  -- 5. Reject duplicate per (restaurant_id, email)
  if exists (
    select 1 from public.restaurant_members
    where restaurant_id = p_restaurant_id
      and lower(email) = v_email
  ) then
    raise exception 'Member already invited or part of this restaurant.';
  end if;

  -- 6. Server-side account & confirmation lookup in auth.users
  select u.id, u.email_confirmed_at
  into v_user_id, v_confirmed_at
  from auth.users u
  where lower(u.email) = v_email
  limit 1;

  -- 7. Insert membership row
  -- ACTIVE with profile_id ONLY if the profile exists AND email is confirmed
  if v_user_id is not null and v_confirmed_at is not null and exists (select 1 from public.profiles where id = v_user_id) then
    insert into public.restaurant_members (
      restaurant_id, profile_id, email, role, status, created_at, updated_at
    ) values (
      p_restaurant_id, v_user_id, v_email, p_role, 'ACTIVE', v_now, v_now
    ) returning * into v_member;
  else
    insert into public.restaurant_members (
      restaurant_id, profile_id, email, role, status, created_at, updated_at
    ) values (
      p_restaurant_id, null, v_email, p_role, 'PENDING', v_now, v_now
    ) returning * into v_member;
  end if;

  -- Return uniform restaurant_members record shape
  return v_member;
end;
$$;

revoke execute on function public.invite_member(uuid, text, public.app_role) from public, anon;
grant execute on function public.invite_member(uuid, text, public.app_role) to authenticated;

-- ------------------------------------------------------------------------------
-- 5. SAFE PENDING MEMBERSHIP CLAIM FUNCTION & TRIGGER
-- ------------------------------------------------------------------------------
create or replace function public.claim_pending_memberships()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Claim ONLY when email is confirmed:
  -- - On INSERT when email_confirmed_at is already set (e.g., confirmations disabled)
  -- - On UPDATE when email_confirmed_at transitions from NULL to NOT NULL
  if (
    (TG_OP = 'INSERT' and NEW.email_confirmed_at is not null) or
    (TG_OP = 'UPDATE' and OLD.email_confirmed_at is null and NEW.email_confirmed_at is not null)
  ) then
    -- Ensure user profile row exists in public.profiles before attaching profile_id
    insert into public.profiles (id, email, name, platform_role, created_at, updated_at)
    values (
      NEW.id,
      lower(NEW.email),
      coalesce(NEW.raw_user_meta_data->>'name', split_part(NEW.email, '@', 1)),
      null,
      now(),
      now()
    )
    on conflict (id) do nothing;

    -- Atomically activate pending invitations matching confirmed email
    update public.restaurant_members
    set profile_id = NEW.id,
        status = 'ACTIVE',
        updated_at = now()
    where lower(email) = lower(NEW.email)
      and profile_id is null
      and status = 'PENDING';
  end if;

  return NEW;
end;
$$;

revoke execute on function public.claim_pending_memberships() from public, anon;

drop trigger if exists tr_claim_pending_memberships on auth.users;
create trigger tr_claim_pending_memberships
  after insert or update on auth.users
  for each row execute procedure public.claim_pending_memberships();

-- ------------------------------------------------------------------------------
-- FILE: 011_subscription_requests.sql
-- ------------------------------------------------------------------------------

create table public.subscription_requests (
  id uuid primary key default gen_random_uuid(),
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  requester_profile_id uuid not null references public.profiles(id) on delete restrict,
  requested_plan public.plan_code not null,
  payment_method text not null check (payment_method in ('INSTAPAY', 'VODAFONE_CASH', 'FREE')),
  payment_number text not null default '',
  payment_reference text not null default '',
  amount numeric(10, 2) not null check (amount >= 0),
  proof_path text,
  status text not null default 'PENDING' check (status in ('PENDING', 'APPROVED', 'REJECTED')),
  reviewer_profile_id uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  admin_notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint subscription_request_payment_details check (
    (payment_method = 'FREE' and payment_number = '' and amount = 0 and proof_path is null)
    or
    (payment_method <> 'FREE' and length(trim(payment_number)) > 0 and amount > 0 and proof_path is not null)
  ),
  constraint subscription_request_proof_tenant_path check (
    proof_path is null or proof_path like restaurant_id::text || '/' || id::text || '/%'
  )
);

create index subscription_requests_restaurant_created_idx
  on public.subscription_requests (restaurant_id, created_at desc);
create index subscription_requests_pending_created_idx
  on public.subscription_requests (created_at desc)
  where status = 'PENDING';
create unique index subscription_requests_one_pending_per_restaurant_idx
  on public.subscription_requests (restaurant_id)
  where status = 'PENDING';

alter table public.subscription_requests enable row level security;
create policy subscription_requests_owner_read
  on public.subscription_requests for select to authenticated
  using (public.is_restaurant_member(restaurant_id, array['RESTAURANT_OWNER']::public.app_role[]));
create policy subscription_requests_owner_create
  on public.subscription_requests for insert to authenticated
  with check (
    requester_profile_id = (select auth.uid())
    and status = 'PENDING'
    and reviewer_profile_id is null
    and reviewed_at is null
    and public.is_restaurant_member(restaurant_id, array['RESTAURANT_OWNER']::public.app_role[])
  );
create policy subscription_requests_admin_update
  on public.subscription_requests for update to authenticated
  using (public.is_super_admin())
  with check (public.is_super_admin());

grant select, insert, update on public.subscription_requests to authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'subscription-proofs',
  'subscription-proofs',
  false,
  5242880,
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
set public = false,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

create policy subscription_proofs_owner_upload
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'subscription-proofs'
    and public.is_restaurant_member(
      ((storage.foldername(name))[1])::uuid,
      array['RESTAURANT_OWNER']::public.app_role[]
    )
    and lower(storage.extension(name)) in ('jpg', 'jpeg', 'png', 'webp')
  );
create policy subscription_proofs_owner_or_admin_read
  on storage.objects for select to authenticated
  using (
    bucket_id = 'subscription-proofs'
    and (
      public.is_super_admin()
      or public.is_restaurant_member(
        ((storage.foldername(name))[1])::uuid,
        array['RESTAURANT_OWNER']::public.app_role[]
      )
    )
  );
create policy subscription_proofs_owner_delete
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'subscription-proofs'
    and public.is_restaurant_member(
      ((storage.foldername(name))[1])::uuid,
      array['RESTAURANT_OWNER']::public.app_role[]
    )
  );

grant insert on public.notifications to authenticated;
create policy notifications_admin_insert
  on public.notifications for insert to authenticated
  with check (public.is_super_admin());

create or replace function public.review_subscription_request(
  p_request_id uuid,
  p_decision text,
  p_admin_notes text,
  p_reviewer_profile_id uuid
)
returns setof public.subscription_requests
language plpgsql
set search_path = public
as $$
declare
  v_request public.subscription_requests;
  v_now timestamptz := now();
  v_expires timestamptz := now() + interval '1 year';
  v_status text;
begin
  if not public.is_super_admin()
     or p_reviewer_profile_id is distinct from (select auth.uid()) then
    raise exception 'Only the authenticated super administrator can review subscription requests.';
  end if;

  if p_decision not in ('APPROVED', 'REJECTED') then
    raise exception 'Invalid subscription request decision.';
  end if;

  select *
    into v_request
    from public.subscription_requests
    where id = p_request_id
    for update;

  if not found then
    raise exception 'Subscription request not found.';
  end if;
  if v_request.status <> 'PENDING' then
    raise exception 'This subscription request has already been reviewed.';
  end if;

  update public.subscription_requests
     set status = p_decision,
         reviewer_profile_id = p_reviewer_profile_id,
         reviewed_at = v_now,
         admin_notes = coalesce(p_admin_notes, ''),
         updated_at = v_now
   where id = p_request_id
   returning * into v_request;

  if p_decision = 'APPROVED' then
    insert into public.subscriptions (
      id, restaurant_id, plan, starts_at, expires_at, status, notes, created_at, updated_at
    )
    values (
      gen_random_uuid(),
      v_request.restaurant_id,
      v_request.requested_plan,
      v_now,
      v_expires,
      'ACTIVE',
      'Approved payment request ' || v_request.id::text,
      v_now,
      v_now
    )
    on conflict (restaurant_id) do update
       set plan = excluded.plan,
           starts_at = excluded.starts_at,
           expires_at = excluded.expires_at,
           status = 'ACTIVE',
           notes = excluded.notes,
           updated_at = excluded.updated_at;
  end if;

  v_status := lower(p_decision);
  insert into public.notifications (
    id, restaurant_id, profile_id, title, body, created_at, updated_at
  )
  select
    gen_random_uuid(),
    v_request.restaurant_id,
    member.profile_id,
    'Subscription request ' || v_status,
    case
      when p_decision = 'APPROVED' then
        'Your ' || v_request.requested_plan::text || ' plan is active until ' || v_expires::date::text || '.'
      else
        'Your request for the ' || v_request.requested_plan::text || ' plan was not approved.'
          || case when length(coalesce(p_admin_notes, '')) > 0 then ' Admin note: ' || p_admin_notes else '' end
    end,
    v_now,
    v_now
  from public.restaurant_members member
  where member.restaurant_id = v_request.restaurant_id
    and member.role = 'RESTAURANT_OWNER'
    and member.status = 'ACTIVE'
    and member.profile_id is not null;

  insert into public.audit_logs (
    id, restaurant_id, actor_profile_id, actor_role, action, entity_type, entity_id, metadata, created_at, updated_at
  )
  values (
    gen_random_uuid(),
    v_request.restaurant_id,
    p_reviewer_profile_id,
    'SUPER_ADMIN',
    'subscription_request.' || v_status,
    'subscription_request',
    v_request.id,
    jsonb_build_object('plan', v_request.requested_plan),
    v_now,
    v_now
  );

  return next v_request;
end;
$$;

revoke all on function public.review_subscription_request(uuid, text, text, uuid) from public, anon;
grant execute on function public.review_subscription_request(uuid, text, text, uuid) to authenticated;

